-- Reassess every Nordic Hamstring Curl source, remove an unrelated inherited
-- calf-raise citation, and replace the empty baseline with exact working
-- specifications. Human media, graph, calibration, content, and publication
-- approvals remain quarantined and are never inferred by this migration.

DO $$
DECLARE
  migration_key CONSTANT TEXT := '464_coaching_nordic_hamstring_family_audit_hardening';
  research_version CONSTANT TEXT := '2026-08-02.76';
  canonical_id CONSTANT UUID := '03894b45-360d-444b-a142-6771ce6df7dd';
  source_ids CONSTANT BIGINT[] := ARRAY[4,574,839];
  source_variant_ids CONSTANT UUID[] := ARRAY[
    'd27b89ec-6173-4d4e-b909-b859610626b9'::UUID,
    'a3424503-52f1-4303-8549-1aaa9487091e'::UUID,
    '934fa3fd-a045-4db4-b973-a4b6401038cc'::UUID];
  archived_definition_ids CONSTANT UUID[] := ARRAY[
    '3dc7851c-4551-4296-8108-baa0f4c9e66f'::UUID,
    '77da4d2d-ca77-4e9a-aa47-f159592a232e'::UUID];
  eccentric_variant CONSTANT UUID := '12796771-cd0b-4344-ab3b-e91f579b5473';
  band_variant CONSTANT UUID := 'a4e727f1-6e9b-41d5-aa10-88a9a15a3a2c';
  unassisted_variant CONSTANT UUID := '8d3befd9-33a1-4686-a421-9d766c540df9';
  isometric_variant CONSTANT UUID := 'ee63d821-8e03-4402-b1a5-355705ce43fc';
  active_variant_ids CONSTANT UUID[] := ARRAY[eccentric_variant,band_variant,unassisted_variant,isometric_variant];
  slider_eccentric_variant CONSTANT UUID := '2985c2f2-acfc-46c4-baeb-db578491bcdf';
  slider_full_cycle_variant CONSTANT UUID := '3cb62825-50d0-4464-8415-142d97cc2d3d';
  slider_short_range_variant CONSTANT UUID := '6a655995-f781-45d4-8abc-5dc125e79bc8';
  current_video_ids CONSTANT TEXT[] := ARRAY['_e9vFU9-tkc','6NCN6kOagfY','IiofP9cn_nc','6_WWA3cQF-w','kLE6k4DYgzQ'];
  protected_count INTEGER;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 WHERE id=canonical_id AND slug='nordic-hamstring-curl')
    OR (SELECT count(*) FROM coaching.exercise_definition_source_v1 WHERE definition_id=canonical_id AND legacy_exercise_id=ANY(source_ids))<>3
    OR (SELECT count(*) FROM coaching.exercise_variant_v1 WHERE id=ANY(source_variant_ids) AND definition_id=canonical_id)<>3
    OR (SELECT count(*) FROM coaching.exercise_definition_v1 WHERE id=ANY(archived_definition_ids) AND status='archived')<>2
    OR NOT EXISTS(SELECT 1 FROM coaching.exercise_variant_v1 v JOIN coaching.exercise_definition_v1 d ON d.id=v.definition_id WHERE v.id=slider_eccentric_variant AND d.slug='hamstring-slider-curl')
    OR NOT EXISTS(SELECT 1 FROM coaching.exercise_variant_v1 v JOIN coaching.exercise_definition_v1 d ON d.id=v.definition_id WHERE v.id=slider_full_cycle_variant AND d.slug='hamstring-slider-curl')
    OR NOT EXISTS(SELECT 1 FROM coaching.exercise_variant_v1 v JOIN coaching.exercise_definition_v1 d ON d.id=v.definition_id WHERE v.id=slider_short_range_variant AND d.slug='hamstring-slider-curl') THEN
    RAISE EXCEPTION '% prerequisite identity state is missing or drifted',migration_key;
  END IF;
  IF EXISTS(SELECT 1 FROM coaching.exercise_variant_v1 WHERE id=ANY(active_variant_ids) AND definition_id<>canonical_id) THEN
    RAISE EXCEPTION '% working variant UUID is already owned by another definition',migration_key;
  END IF;

  SELECT COALESCE(sum(n),0) INTO protected_count FROM (
    SELECT count(*) n FROM coaching.exercise_definition_v1 WHERE id=canonical_id AND (reviewed_by IS NOT NULL OR approved_by IS NOT NULL OR last_reviewed_at IS NOT NULL)
    UNION ALL SELECT count(*) FROM coaching.exercise_section_evidence_v1 WHERE definition_id=canonical_id AND reviewer_user_id IS NOT NULL
    UNION ALL SELECT count(*) FROM coaching.exercise_media_candidate_v1 WHERE definition_id=canonical_id AND (reviewer_user_id IS NOT NULL OR reviewed_at IS NOT NULL OR review_status IN('approved'))
    UNION ALL SELECT count(*) FROM coaching.exercise_alternate_assessment_v1 WHERE definition_id=canonical_id AND reviewer_user_id IS NOT NULL
    UNION ALL SELECT count(*) FROM coaching.exercise_delivery_profile_v1 WHERE variant_id=ANY(source_variant_ids||active_variant_ids) AND status='approved'
    UNION ALL SELECT count(*) FROM coaching.exercise_relationship_v1 WHERE (from_variant_id=ANY(source_variant_ids||active_variant_ids) OR to_variant_id=ANY(source_variant_ids||active_variant_ids)) AND (reviewed_by IS NOT NULL OR review_status IN('approved'))
    UNION ALL SELECT count(*) FROM coaching.exercise_score_calibration_v1 WHERE variant_id=ANY(source_variant_ids||active_variant_ids) AND (reviewed_by IS NOT NULL OR status='approved')
  ) protected;
  IF protected_count<>0 THEN RAISE EXCEPTION '% refuses to replace human review',migration_key; END IF;

  UPDATE coaching.exercise_section_evidence_v1 SET review_status='superseded',updated_at=now()
  WHERE definition_id=canonical_id AND review_status='candidate' AND reviewer_user_id IS NULL;
  UPDATE coaching.exercise_media_candidate_v1 SET review_status='superseded',updated_at=now()
  WHERE definition_id=canonical_id AND review_status='candidate' AND reviewer_user_id IS NULL;
  UPDATE coaching.exercise_alternate_assessment_v1 SET review_status='superseded',updated_at=now()
  WHERE definition_id=canonical_id AND review_status='candidate' AND reviewer_user_id IS NULL;
  DELETE FROM coaching.exercise_relationship_v1
  WHERE (from_variant_id=ANY(source_variant_ids||active_variant_ids) OR to_variant_id=ANY(source_variant_ids||active_variant_ids))
    AND reviewed_by IS NULL AND review_status<>'approved';
  DELETE FROM coaching.exercise_score_calibration_v1
  WHERE variant_id=ANY(source_variant_ids||active_variant_ids) AND reviewed_by IS NULL AND status<>'approved';

  UPDATE coaching.exercise_definition_source_v1 SET
    source_kind=CASE WHEN legacy_exercise_id=4 THEN 'legacy_migration' ELSE 'duplicate_consolidation' END,
