        WHEN 4 THEN 'source_only_claims_eccentric_posterior_chain_and_injury_proofing_without_anchor_range_tempo_return_or_dose_contract'
        WHEN 574 THEN 'source_names_assistance_and_concentric_intent_without_assistance_interface_anchor_range_tempo_or_return_contract'
        ELSE 'source_names_owned_angle_and_about_six_seconds_without_support_slope_knee_angle_hip_angle_entry_or_exit_contract' END,
      'invalidPriorCitationRemoved','https://pubmed.ncbi.nlm.nih.gov/38156065/',
      'invalidPriorCitationReason','calf_raise_hypertrophy_study_not_nordic_hamstring_evidence',
