    athlete_support_json=jsonb_build_object('whatItIs','Kneel with both ankles secured and keep shoulders, hips, and knees in one line while you lower, hold, or return exactly as assigned.','before',jsonb_build_array('Confirm exact variant, anchor, support slope, assistance, range, tempo or hold, catch, return, sets, rest, and stop signal.','Inspect padding, anchor, assistance path, and clear fall space with the coach.','Report pain, cramp, unusual soreness, weakness, fear, or uncertainty before starting.'),'during',jsonb_build_array('Keep hips from folding or leading.','Follow the assigned lower, hold, catch, and return strategy; do not improvise a concentric rep.','Catch with ready hands when assigned and reset completely.','Stop before range, tempo, body line, breathing, or confidence changes.'),'expectedSensations',jsonb_build_array('high_hamstring_tension','controlled_front_of_body_fall','firm_trunk_and_glute support'),'notExpected',jsonb_build_array('sharp_or_increasing_pain','sudden_pull_or_pop','uncontrolled_cramp','knee_or_ankle_pressure','dizziness','band_contact_at_neck_or_face','surprise_fall'),'selfChecks',jsonb_build_array('exact_anchor_and_variant','shoulders_hips_knees_remain_aligned','assigned_tempo_angle_and_range','planned_catch_and_return','full_reset_and_calm_breathing'),'accessibility',jsonb_build_array('shorter_range_target','more_band_assistance','eccentric_catch_reset','fixed_angle_hold','hamstring_slider_curl','longer_rest','fewer_repetitions'),'stopSignal','Stop immediately, catch safely, unload the anchor or band, tell the coach what changed, and do not retry until symptoms, identity, dose, equipment, and recovery are re-evaluated.'),
